package in.foodcart.service;
import in.foodcart.data.*; import in.foodcart.domain.*; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*;
@Service public class CheckoutService { private final VendorRepository vendors;private final MenuItemRepository items;private final OrderRepository orders;private final HistoryRepository history;private final CustomerRepository customers; public CheckoutService(VendorRepository v,MenuItemRepository i,OrderRepository o,HistoryRepository h,CustomerRepository c){vendors=v;items=i;orders=o;history=h;customers=c;} public record Line(String menuItemId,int quantity,BigDecimal displayedPrice,String portion){} public record Request(String vendorId,String type,String dineInNote,List<Line> items){} public OrderEntity create(String customerId,Request request){VendorEntity v=vendors.findById(request.vendorId()).orElseThrow(()->new IllegalArgumentException("Vendor not found"));if(v.status!=VendorStatus.OPEN)throw new IllegalStateException("This vendor is currently closed.");OrderEntity o=new OrderEntity();o.vendorId=v.id;o.customerId=customerId;o.customerMobile=customers.findById(customerId).orElseThrow(()->new SecurityException("Customer not found")).mobile;o.type=request.type();o.dineInNote=request.dineInNote();for(Line line:request.items()){MenuItemEntity m=items.findByIdAndVendorId(line.menuItemId(),v.id).orElseThrow(()->new IllegalStateException("An item no longer exists."));String portion="HALF".equals(line.portion())?"HALF":"FULL";BigDecimal price="HALF".equals(portion)?m.halfPrice:m.price;if(!m.active||!m.available||("HALF".equals(portion)&&(!m.halfAvailable||price==null)))throw new IllegalStateException(m.name+" is no longer available.");if(line.displayedPrice()!=null&&price.compareTo(line.displayedPrice())!=0)throw new IllegalStateException("Price of "+m.name+" has changed. Please review your cart.");if(line.quantity()<1)throw new IllegalArgumentException("Quantity must be at least 1");OrderEntity.Item snap=new OrderEntity.Item();snap.menuItemId=m.id;snap.name=m.name;snap.portion=portion;snap.price=price;snap.quantity=line.quantity();snap.lineTotal=price.multiply(BigDecimal.valueOf(line.quantity()));o.items.add(snap);}if(o.items.isEmpty())throw new IllegalArgumentException("Cart is empty");o.subtotal=o.items.stream().map(x->x.lineTotal).reduce(BigDecimal.ZERO,BigDecimal::add);o.total=o.subtotal;o.orderNumber=1000+orders.count()+1;OrderEntity saved=orders.save(o);CustomerVendorHistoryEntity h=history.findByCustomerIdAndVendorId(customerId,v.id).orElseGet(()->{CustomerVendorHistoryEntity x=new CustomerVendorHistoryEntity();x.customerId=customerId;x.vendorId=v.id;return x;});h.totalOrders++;h.lastOrderedAt=Instant.now();history.save(h);return saved;} public OrderEntity status(String vendorId,String id,OrderStatus target){OrderEntity o=orders.findByIdAndVendorId(id,vendorId).orElseThrow(()->new SecurityException("Order not found"));boolean valid=(o.status==OrderStatus.PLACED&&(target==OrderStatus.ACCEPTED||target==OrderStatus.REJECTED))||(o.status==OrderStatus.ACCEPTED&&target==OrderStatus.PREPARING)||(o.status==OrderStatus.PREPARING&&(target==OrderStatus.READY||target==OrderStatus.COMPLETED))||(o.status==OrderStatus.READY&&target==OrderStatus.COMPLETED);if(!valid)throw new IllegalStateException("Invalid order status transition");o.status=target;Instant now=Instant.now();if(target==OrderStatus.ACCEPTED)o.acceptedAt=now;if(target==OrderStatus.PREPARING)o.preparingAt=now;if(target==OrderStatus.READY)o.readyAt=now;if(target==OrderStatus.COMPLETED)o.completedAt=now;if(target==OrderStatus.REJECTED)o.rejectedAt=now;return orders.save(o);} }
